(23,'speaking','Full Speaking · Day 23','published',$json${"version":"speaking-day-23-v1","part1":{"topic":"TOPIC 24. HISTORY","questions":[{"key":"p1_q1","text":"Do you think history is important?"},{"key":"p1_q2","text":"Do you like to learn about history?"},{"key":"p1_q3","text":"Do you think the internet is a good place to learn about history?"}]},"part2":{"key":"p2_main","topic":"TOPIC 23. PERSON WHO FACED DIFFICULTIES BUT SUCCEEDED","prompt":"Describe a person who met difficulties but succeeded.","bullets":["who this friend is","what the achievement was","what he or she did","why you were proud of your friend's achievement"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 23. SUCCESS","questions":[{"key":"p3_q1","text":"How would you define success?"},{"key":"p3_q2","text":"In general, how do people judge or, assess the success of others?"},{"key":"p3_q3","text":"What does it take to become successful?"},{"key":"p3_q4","text":"Why is it that some people achieve success faster?"},{"key":"p3_q5","text":"What factors lead to success?"}]}}$json$::jsonb,now(),now()),
(24,'speaking','Full Speaking · Day 24','published',$json${"version":"speaking-day-24-v1","part1":{"topic":"TOPIC 25. OLD BUILDINGS","questions":[{"key":"p1_q1","text":"Do you prefer living in an old building or a modern house?"},{"key":"p1_q2","text":"Should old buildings be preserved?"},{"key":"p1_q3","text":"Are there any old buildings you want to see in the future?"},{"key":"p1_q4","text":"What aspect of culture do old buildings reflect?"},{"key":"p1_q5","text":"How do old buildings affect the appearance of a place?"}]},"part2":{"key":"p2_main","topic":"TOPIC 24. TECHNOLOGICAL PROBLEM","prompt":"Describe a challenging technological problem you faced.","bullets":["what the problem was","when and where you faced it","how challenging it was","how you solved it"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 24. AI","questions":[{"key":"p3_q1","text":"Have you ever had any experience with things related to AI?"},{"key":"p3_q2","text":"Have you ever used AI-based technology?"}]}}$json$::jsonb,now(),now()),
(26,'speaking','Full Speaking · Day 26','published',$json${"version":"speaking-day-26-v1","part1":{"topic":"TOPIC 26. FILMS","questions":[{"key":"p1_q1","text":"What kinds of movies do you like best?"},{"key":"p1_q2","text":"How often do you go to a cinema to watch a movie?"},{"key":"p1_q3","text":"Did you usually go to the cinema when you were a kid?"},{"key":"p1_q4","text":"What was the first film that you watched?"},{"key":"p1_q5","text":"Do you like to watch movies alone or with your friends?"},{"key":"p1_q6","text":"Do you like to go to the cinema with your friends?"},{"key":"p1_q7","text":"Do you prefer foreign films or films made in your country?"}]},"part2":{"key":"p2_main","topic":"TOPIC 25. PERSON WHO HELPED YOU SOLVE A PROBLEM","prompt":"Describe a person who did something to help you solve a problem.","bullets":["what the problem was","when and where you faced it","how this person solved it","how you felt about the experience"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 25. INTELLIGENCE","questions":[{"key":"p3_q1","text":"Are people born clever or need to learn to be clever?"},{"key":"p3_q2","text":"Why are some children more intelligent than others?"},{"key":"p3_q3","text":"How do children become smart at school?"},{"key":"p3_q4","text":"Do you think society needs people with different types of intelligence?"},{"key":"p3_q5","text":"Does modern society need talents of all kinds?"},{"key":"p3_q6","text":"Do you think smart people are happy?"},{"key":"p3_q7","text":"Do you think smart people are happier than others?"},{"key":"p3_q8","text":"Do you think smart people are not good at certain things?"},{"key":"p3_q9","text":"Do you think the intelligence of a person is important?"},{"key":"p3_q10","text":"What ways do people use to judge someone's intelligence?"},{"key":"p3_q11","text":"Do you think there is anything that intelligent people find difficult to do?"}]}}$json$::jsonb,now(),now())
